/* Go: pdu.EMBInfo. EMBInfo is the 7 information bits of an EMB PDU without the QR(16,7,6) parity, in bits 7 to 1 of one octet as IPSC carries them. */
typedef uint8_t dmrgo_pdu_emb_info_t;
/* Go: pdu.Format. Format is the 4-bit Data Packet Format (DPF) of a data header (ETSI TS 102 361-1 clause 9.3.17). */
typedef uint8_t dmrgo_pdu_format_t;
/* Go: pdu.NetworkModel. NetworkModel is the MODEL field of a System Identity Code (ETSI TS 102 361-4 Table 6.5). */
typedef uint8_t dmrgo_pdu_network_model_t;
/* Go: pdu.Opcode0x38Hint. Opcode0x38Hint is the likely meaning of a CSBK with opcode 0x38, which is BS_Dwn_Act in Tier II and TD_GRANT_MI in Tier III. */
typedef uint8_t dmrgo_pdu_opcode0x38_hint_t;
/* Go: pdu.ServiceType. ServiceType is the higher layer service that a USBD carries (ETSI TS 102 361-1 clause 9.3.43). */
typedef uint8_t dmrgo_pdu_service_type_t;
/* Go: pdu.SlotTypeInfo. SlotTypeInfo is the 8 information bits of a SLOT PDU without the Golay(20,8) parity, as IPSC carries them: the color code in the high 4 bits and the Data Type in the low 4 bits. */
typedef uint8_t dmrgo_pdu_slot_type_info_t;
