/* Go: bs.ActivationAny. ActivationAny wakes up on any valid burst with the own color code, or on any network burst ("MS established timing"). */
#define DMRGO_BS_ACTIVATION_ANY ((dmrgo_bs_activation_t)0)
/* Go: bs.ActivationWakeup. ActivationWakeup wakes up only on a BS_Dwn_Act CSBK with the own color code, or on a network burst ("BS established timing", ETSI TS 102 361-2 clause 5.1.1.1). */
#define DMRGO_BS_ACTIVATION_WAKEUP ((dmrgo_bs_activation_t)1)
/* Go: bs.DefaultDataQueue. DefaultDataQueue is the number of data and CSBK bursts per slot that wait for the outbound channel. */
#define DMRGO_BS_DEFAULT_DATA_QUEUE 4
/* Go: bs.DefaultInactivity. DefaultInactivity is T_MSInactiv, the time without inbound activity after which the Repeater hibernates (ETSI TS 102 361-1 clause F.1). */
#define DMRGO_BS_DEFAULT_INACTIVITY INT64_C(5000000000)
/* Go: bs.DefaultPending. DefaultPending is the number of refused sources per slot that wait for the slot. */
#define DMRGO_BS_DEFAULT_PENDING 8
/* Go: bs.DefaultPendingAge. DefaultPendingAge is the longest time a source waits for a slot. */
#define DMRGO_BS_DEFAULT_PENDING_AGE INT64_C(30000000000)
/* Go: bs.MaxDataQueue. MaxDataQueue is the most data and CSBK bursts per slot that wait for the outbound channel. */
#define DMRGO_BS_MAX_DATA_QUEUE 16
/* Go: bs.MaxOutputs. MaxOutputs is the most outputs that one call of a Repeater method appends. */
#define DMRGO_BS_MAX_OUTPUTS 10
/* Go: bs.MaxPending. MaxPending is the most sources per slot that wait for the slot. */
#define DMRGO_BS_MAX_PENDING 16
/* Go: bs.ModeNetwork. ModeNetwork is the slot arbiter of a network server without RF: it regenerates and forwards the bursts of the owner of each slot and makes no CACH, hang time or Idle bursts. */
#define DMRGO_BS_MODE_NETWORK ((dmrgo_bs_mode_t)1)
/* Go: bs.ModeRF. ModeRF is a repeater or hotspot with a transmitter: one outbound burst per 30 ms slot, hang time bursts, Idle bursts and hibernation. */
#define DMRGO_BS_MODE_RF ((dmrgo_bs_mode_t)0)
/* Go: bs.OutputBurst. OutputBurst is a burst to send at Due to the places in To. */
#define DMRGO_BS_OUTPUT_BURST ((dmrgo_bs_output_kind_t)1)
/* Go: bs.OutputCallEnd. OutputCallEnd is the end of the call or data on a slot. */
#define DMRGO_BS_OUTPUT_CALL_END ((dmrgo_bs_output_kind_t)3)
/* Go: bs.OutputCallStart. OutputCallStart is a source that took a slot. */
#define DMRGO_BS_OUTPUT_CALL_START ((dmrgo_bs_output_kind_t)2)
/* Go: bs.OutputDekey. OutputDekey is the start of hibernation in ModeRF. */
#define DMRGO_BS_OUTPUT_DEKEY ((dmrgo_bs_output_kind_t)6)
/* Go: bs.OutputKey. OutputKey is the wakeup of the transmitter in ModeRF. */
#define DMRGO_BS_OUTPUT_KEY ((dmrgo_bs_output_kind_t)5)
/* Go: bs.OutputRejected. OutputRejected is a source that the Repeater refused. */
#define DMRGO_BS_OUTPUT_REJECTED ((dmrgo_bs_output_kind_t)4)
/* Go: bs.ReasonHangTime. ReasonHangTime is a call to another target in the call hang time of the slot (ETSI TS 102 361-1 clause 5.2.1.4). */
#define DMRGO_BS_REASON_HANG_TIME ((dmrgo_bs_reason_t)2)
/* Go: bs.ReasonRejected. ReasonRejected is a call that the caller refused with Repeater.Reject. */
#define DMRGO_BS_REASON_REJECTED ((dmrgo_bs_reason_t)4)
/* Go: bs.ReasonSlotBusy. ReasonSlotBusy is a slot that another source owns. */
#define DMRGO_BS_REASON_SLOT_BUSY ((dmrgo_bs_reason_t)1)
/* Go: bs.ReasonTimeout. ReasonTimeout is a call that ran longer than Config.Timeout. */
#define DMRGO_BS_REASON_TIMEOUT ((dmrgo_bs_reason_t)3)
/* Go: bs.ServiceData. ServiceData is a data transfer: a data header and its blocks. */
#define DMRGO_BS_SERVICE_DATA ((dmrgo_bs_service_t)1)
/* Go: bs.ServiceVoice. ServiceVoice is a voice call. */
#define DMRGO_BS_SERVICE_VOICE ((dmrgo_bs_service_t)0)
/* Go: bs.SlotCallHang. SlotCallHang is the call hang time after a voice call: only a call to the same target takes the slot, and it gets Terminators with the call LC. */
#define DMRGO_BS_SLOT_CALL_HANG ((dmrgo_bs_slot_state_t)3)
/* Go: bs.SlotData. SlotData repeats a data header and its blocks. */
#define DMRGO_BS_SLOT_DATA ((dmrgo_bs_slot_state_t)2)
/* Go: bs.SlotDataHang. SlotDataHang is the data hang time after confirmed data: it gets TD_LC and waits for the response. */
#define DMRGO_BS_SLOT_DATA_HANG ((dmrgo_bs_slot_state_t)4)
/* Go: bs.SlotIdle. SlotIdle is the channel hang time: the slot is free and gets Idle bursts. */
#define DMRGO_BS_SLOT_IDLE ((dmrgo_bs_slot_state_t)0)
/* Go: bs.SlotRejected. SlotRejected drops a call that timed out or was rejected until it ends. */
#define DMRGO_BS_SLOT_REJECTED ((dmrgo_bs_slot_state_t)5)
/* Go: bs.SlotTime. SlotTime is the time of one outbound burst with its CACH, and the period of Tick in ModeRF (ETSI TS 102 361-1 clause 4.2.2). */
#define DMRGO_BS_SLOT_TIME 30000000
/* Go: bs.SlotVoice. SlotVoice repeats a voice call. */
#define DMRGO_BS_SLOT_VOICE ((dmrgo_bs_slot_state_t)1)
/* Go: bs.StateHangtime. StateHangtime is keyed with both slots free. */
#define DMRGO_BS_STATE_HANGTIME ((dmrgo_bs_state_t)1)
/* Go: bs.StateHibernating. StateHibernating has the transmitter off. */
#define DMRGO_BS_STATE_HIBERNATING ((dmrgo_bs_state_t)0)
/* Go: bs.StateRepeatingBoth. StateRepeatingBoth repeats both slots. */
#define DMRGO_BS_STATE_REPEATING_BOTH ((dmrgo_bs_state_t)4)
/* Go: bs.StateRepeatingSlot1. StateRepeatingSlot1 repeats slot 1. */
#define DMRGO_BS_STATE_REPEATING_SLOT1 ((dmrgo_bs_state_t)2)
/* Go: bs.StateRepeatingSlot2. StateRepeatingSlot2 repeats slot 2. */
#define DMRGO_BS_STATE_REPEATING_SLOT2 ((dmrgo_bs_state_t)3)
/* Go: bs.ToNetwork. ToNetwork sends the burst to the network: in ModeNetwork to the peers other than Output.From, in ModeRF to the network that the hotspot or repeater is linked to. */
#define DMRGO_BS_TO_NETWORK ((dmrgo_bs_dest_t)2)
