/* Go: dvsi.MaxPacketLen. MaxPacketLen is the length of the longest packet that Parse accepts. */
#define DMRGO_DVSI_MAX_PACKET_LEN 388
/* Go: dvsi.MaxProductLen. MaxProductLen and MaxVersionLen are the longest product name and version string that a Codec keeps (AMBE-3000R manual Tables 67 and 69). */
#define DMRGO_DVSI_MAX_PRODUCT_LEN 16
/* Go: dvsi.MaxSamples. MinSamples and MaxSamples bound the samples of a SPEECHD field (AMBE-3000R manual Table 98). */
#define DMRGO_DVSI_MAX_SAMPLES 164
/* Go: dvsi.MaxVersionLen. MaxProductLen and MaxVersionLen are the longest product name and version string that a Codec keeps (AMBE-3000R manual Tables 67 and 69). */
#define DMRGO_DVSI_MAX_VERSION_LEN 48
/* Go: dvsi.MinBits. MinBits and MaxBits bound the bits of a CHAND field (AMBE-3000R manual Table 106). */
#define DMRGO_DVSI_MIN_BITS 40
/* Go: dvsi.MinSamples. MinSamples and MaxSamples bound the samples of a SPEECHD field (AMBE-3000R manual Table 98). */
#define DMRGO_DVSI_MIN_SAMPLES 156
/* Go: dvsi.StartByte. StartByte is the first byte of every packet (AMBE-3000R manual section 6.5.1). */
#define DMRGO_DVSI_START_BYTE 97
/* Go: dvsi.TypeChannel. channel bits to decode, or encoded by the chip */
#define DMRGO_DVSI_TYPE_CHANNEL ((dmrgo_dvsi_packet_type_t)1)
/* Go: dvsi.TypeControl. configuration requests and their responses */
#define DMRGO_DVSI_TYPE_CONTROL ((dmrgo_dvsi_packet_type_t)0)
/* Go: dvsi.TypeSpeech. speech samples to encode, or decoded by the chip */
#define DMRGO_DVSI_TYPE_SPEECH ((dmrgo_dvsi_packet_type_t)2)
/* Go: voice.DefaultLost. DefaultLost is the time without a burst after which a Receiver ends a call, when ReceiverConfig.Lost is 0. */
#define DMRGO_VOICE_DEFAULT_LOST 1000000000
/* Go: voice.DefaultQueue. DefaultQueue is the number of vocoder slots that a Transmitter buffers when TransmitterConfig.Queue is 0: three bursts. */
#define DMRGO_VOICE_DEFAULT_QUEUE 9
/* Go: voice.EndDataSync. EndDataSync is a data burst other than a terminator. */
#define DMRGO_VOICE_END_DATA_SYNC ((dmrgo_voice_end_reason_t)2)
/* Go: voice.EndIdle. EndIdle is an idle burst. */
#define DMRGO_VOICE_END_IDLE ((dmrgo_voice_end_reason_t)3)
/* Go: voice.EndLost. EndLost is a time of ReceiverConfig.Lost without a burst. */
#define DMRGO_VOICE_END_LOST ((dmrgo_voice_end_reason_t)4)
/* Go: voice.EndSuperseded. EndSuperseded is a new call: an LC with other addresses, or another transport stream. */
#define DMRGO_VOICE_END_SUPERSEDED ((dmrgo_voice_end_reason_t)7)
/* Go: voice.EndSyncLost. EndSyncLost is a transport that lost the signal: Hint.SyncLost or Receiver.Lost. */
#define DMRGO_VOICE_END_SYNC_LOST ((dmrgo_voice_end_reason_t)5)
/* Go: voice.EndTerminator. EndTerminator is a Terminator with LC. */
#define DMRGO_VOICE_END_TERMINATOR ((dmrgo_voice_end_reason_t)1)
/* Go: voice.EndTimeout. EndTimeout is the transmit timeout T_TO of a Transmitter (ETSI TS 102 361-2 clause 6.1). */
#define DMRGO_VOICE_END_TIMEOUT ((dmrgo_voice_end_reason_t)8)
/* Go: voice.EndTransport. EndTransport is the end flag of the transport, Hint.End EndStrong. */
#define DMRGO_VOICE_END_TRANSPORT ((dmrgo_voice_end_reason_t)6)
/* Go: voice.EventCallEnd. EventCallEnd ends a call. */
#define DMRGO_VOICE_EVENT_CALL_END ((dmrgo_voice_event_kind_t)6)
/* Go: voice.EventCallStart. EventCallStart starts a call. */
#define DMRGO_VOICE_EVENT_CALL_START ((dmrgo_voice_event_kind_t)1)
/* Go: voice.EventEmbedded. EventEmbedded is an embedded LC that is not the call LC, such as GPS or a talker alias block. */
#define DMRGO_VOICE_EVENT_EMBEDDED ((dmrgo_voice_event_kind_t)3)
/* Go: voice.EventPIHeader. EventPIHeader is a PI Header of the call. */
#define DMRGO_VOICE_EVENT_PI_HEADER ((dmrgo_voice_event_kind_t)5)
/* Go: voice.EventSessionEnd. EventSessionEnd ends the call hang time with no new call to the same target. */
#define DMRGO_VOICE_EVENT_SESSION_END ((dmrgo_voice_event_kind_t)8)
/* Go: voice.EventSessionStart. EventSessionStart joins a call session in its hang time, from a Terminator with LC. */
#define DMRGO_VOICE_EVENT_SESSION_START ((dmrgo_voice_event_kind_t)7)
/* Go: voice.EventTalkerAlias. EventTalkerAlias is a complete talker alias. */
#define DMRGO_VOICE_EVENT_TALKER_ALIAS ((dmrgo_voice_event_kind_t)4)
/* Go: voice.EventVoice. EventVoice is a voice burst. */
#define DMRGO_VOICE_EVENT_VOICE ((dmrgo_voice_event_kind_t)2)
/* Go: voice.MaxEvents. MaxEvents is the most events that one call of a Receiver method appends. */
#define DMRGO_VOICE_MAX_EVENTS 6
/* Go: voice.MaxHeaders. MaxHeaders is the most Voice LC Headers before burst A. */
#define DMRGO_VOICE_MAX_HEADERS 8
/* Go: voice.MaxOutputs. MaxOutputs is the most outputs that one call of a Transmitter method appends: one burst, and OutputEnded after the last terminator. */
#define DMRGO_VOICE_MAX_OUTPUTS 2
/* Go: voice.MaxQueue. MaxQueue is the most vocoder slots that a Transmitter buffers. */
#define DMRGO_VOICE_MAX_QUEUE 192
/* Go: voice.MaxTerminators. MaxTerminators is the most Terminators with LC at the end of a call. */
#define DMRGO_VOICE_MAX_TERMINATORS 64
/* Go: voice.OriginEmbedded. OriginEmbedded is the embedded LC of bursts B to E (late entry). */
#define DMRGO_VOICE_ORIGIN_EMBEDDED ((dmrgo_voice_origin_t)2)
/* Go: voice.OriginExpected. OriginExpected is the call that Receiver.Expect gave, for voice that came without an LC, such as after a Tier III grant. */
#define DMRGO_VOICE_ORIGIN_EXPECTED ((dmrgo_voice_origin_t)4)
/* Go: voice.OriginHeader. OriginHeader is a Voice LC Header. */
#define DMRGO_VOICE_ORIGIN_HEADER ((dmrgo_voice_origin_t)1)
/* Go: voice.OriginTerminator. OriginTerminator is a Terminator with LC, seen in the call hang time. */
#define DMRGO_VOICE_ORIGIN_TERMINATOR ((dmrgo_voice_origin_t)3)
/* Go: voice.OriginUnknown. OriginUnknown is voice whose LC is not known yet. */
#define DMRGO_VOICE_ORIGIN_UNKNOWN ((dmrgo_voice_origin_t)0)
/* Go: voice.OutputBurst. OutputBurst is a burst to send. */
#define DMRGO_VOICE_OUTPUT_BURST ((dmrgo_voice_output_kind_t)1)
/* Go: voice.OutputEnded. OutputEnded is the end of the transmission. */
#define DMRGO_VOICE_OUTPUT_ENDED ((dmrgo_voice_output_kind_t)2)
/* Go: voice.StateHang. StateHang is the call hang time after a call, in which a new call to the same target continues the session. */
#define DMRGO_VOICE_STATE_HANG ((dmrgo_voice_state_t)3)
/* Go: voice.StateIdle. StateIdle has no call and no session. */
#define DMRGO_VOICE_STATE_IDLE ((dmrgo_voice_state_t)0)
/* Go: voice.StateInCall. StateInCall has a call. */
#define DMRGO_VOICE_STATE_IN_CALL ((dmrgo_voice_state_t)2)
/* Go: voice.StateLateEntry. StateLateEntry has voice whose LC is not known yet. */
#define DMRGO_VOICE_STATE_LATE_ENTRY ((dmrgo_voice_state_t)1)
/* Go: voice.TransmitterEnding. TransmitterEnding pads the last superframe and sends the terminators. */
#define DMRGO_VOICE_TRANSMITTER_ENDING ((dmrgo_voice_transmitter_state_t)3)
/* Go: voice.TransmitterHeader. TransmitterHeader sends the Voice LC Headers and the PI Header. */
#define DMRGO_VOICE_TRANSMITTER_HEADER ((dmrgo_voice_transmitter_state_t)1)
/* Go: voice.TransmitterIdle. TransmitterIdle sends nothing. */
#define DMRGO_VOICE_TRANSMITTER_IDLE ((dmrgo_voice_transmitter_state_t)0)
/* Go: voice.TransmitterTimedOut. TransmitterTimedOut has ended the call after T_TO and waits for Stop, the release of the PTT (ETSI TS 102 361-2 clause 6.1). */
#define DMRGO_VOICE_TRANSMITTER_TIMED_OUT ((dmrgo_voice_transmitter_state_t)4)
/* Go: voice.TransmitterVoice. TransmitterVoice sends voice bursts. */
#define DMRGO_VOICE_TRANSMITTER_VOICE ((dmrgo_voice_transmitter_state_t)2)

